CREATE TYPE "account_type" AS ENUM (
  'public',
  'private',
  'hidden'
);

CREATE TYPE "role_type" AS ENUM (
  'admin',
  'org',
  'gamer'
);

CREATE TYPE "status_type" AS ENUM (
  'live',
  'draft',
  'archived',
  'reported'
);

CREATE TYPE "media_type" AS ENUM (
  'none',
  'photo',
  'video'
);

CREATE TABLE "follows" (
  "following_user_id" integer,
  "followed_user_id" integer,
  "created_at" timestamp NOT NULL,
  PRIMARY KEY ("following_user_id", "followed_user_id")
);

CREATE TABLE "users" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "email" varchar(100) UNIQUE NOT NULL,
  "username" varchar(100) UNIQUE NOT NULL,
  "role" role_type NOT NULL,
  "account" account_type DEFAULT 'public',
  "created_at" timestamp DEFAULT (now()),
  "updated_at" timestamp DEFAULT (now())
);

CREATE TABLE "posts" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" integer,
  "s3_key" varchar(255) DEFAULT null,
  "media" media_type NOT NULL,
  "game" varchar(100),
  "body" text,
  "status" status_type DEFAULT 'live',
  "likes" integer DEFAULT 0,
  "comments" integer DEFAULT 0,
  "created_at" timestamp DEFAULT (now()),
  "updated_at" timestamp DEFAULT (now())
);

CREATE TABLE "liked_posts" (
  "user_id" integer,
  "post_id" integer,
  "created_at" timestamp DEFAULT (now()),
  "updated_at" timestamp DEFAULT (now()),
  PRIMARY KEY ("user_id", "post_id")
);

CREATE TABLE "comments" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" integer,
  "post_id" integer,
  "text" text,
  "created_at" timestamp DEFAULT (now()),
  "updated_at" timestamp DEFAULT (now())
);

COMMENT ON COLUMN "posts"."s3_key" IS 's3 id for content';

COMMENT ON COLUMN "posts"."body" IS 'Content of the post';

COMMENT ON COLUMN "comments"."text" IS 'Content of comment';

ALTER TABLE "follows" ADD FOREIGN KEY ("following_user_id") REFERENCES "users" ("id");

ALTER TABLE "follows" ADD FOREIGN KEY ("followed_user_id") REFERENCES "users" ("id");

ALTER TABLE "posts" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id");

ALTER TABLE "liked_posts" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id");

ALTER TABLE "liked_posts" ADD FOREIGN KEY ("post_id") REFERENCES "posts" ("id");

ALTER TABLE "comments" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id");

ALTER TABLE "comments" ADD FOREIGN KEY ("post_id") REFERENCES "posts" ("id");
